      // A flat rock plate with one boulder silhouette repeated on a lattice. No ceiling, no walls,
      // no scale range: a "cave" with nothing enclosing it and nothing to look at. Same materials
      // and crystal colours as the good sibling.
      const n = v === 0 ? 16 : 20;
      for (let i = 0; i < n; i++) {
        add(`Boulder${i}`, 'Rock', jc([98, 90, 84], rng, 12), [(i % 4) * 12 - 18, 2.5, Math.floor(i / 4) * 12 - 18], [3, 3, 3]);
      }
      clutter(add, rng, { n: 26, r: 24, name: 'Scree', materials: ['Rock', 'Ice', 'Water', 'Neon'], colors: [[100, 92, 84], [130, 200, 240], [58, 110, 138], [110, 190, 236]] });
