      add('Wall_S_L', 'Brick', jc([170, 122, 96], rng), [-7.5, 7, 8], [7, 10, 1]);
      add('Wall_S_R', 'Brick', jc([170, 122, 96], rng), [7.5, 7, 8], [7, 10, 1]);
